function aplicarRevisao(c) {
  const R = CATALOGO_REVISAO, f = R.campos[c.id], r = R.registro[c.id], t = R.thema[c.id], g = R.tags[c.id];
  if (!f && !r && !t && !g) return c;
  const out = {...c, ...f};
  if (r) out.tags = out.tags.replace(/Register::\S+/, "Register::" + r);
  if (t) out.tags = out.tags.replace(/(^| )Thema::\S+/g, "").trim() + " Thema::" + t;
  if (g) out.tags += " " + g;
  return out;
}
